[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param(
  [ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',
  [string]$StatePath=(Join-Path $PSScriptRoot 'state.json'),
  [string]$LogPath=(Join-Path $PSScriptRoot 'events.jsonl')
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$script:Experiment='EXP-081'
$script:RunPaths=@('HKCU:\Software\Microsoft\Windows\CurrentVersion\Run','HKLM:\Software\Microsoft\Windows\CurrentVersion\Run','HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run')
$script:Protected=@('omnissa','vmware horizon','windows app','remote desktop','mstsc','tailscale','securityhealth','defender','credential','bitlocker','firewall','accessibility','windows update','recovery')
function Write-ExpLog([string]$Event,[string]$Result,[hashtable]$Data=@{}){
  $p=Split-Path -Parent $LogPath;if($p -and !(Test-Path -LiteralPath $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null}
  [ordered]@{timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$script:Experiment;action=$Action;event=$Event;result=$Result;data=$Data}|ConvertTo-Json -Compress -Depth 10|Add-Content -LiteralPath $LogPath -Encoding UTF8
}
function Test-IsElevated{$i=[Security.Principal.WindowsIdentity]::GetCurrent();([Security.Principal.WindowsPrincipal]::new($i)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}
function Get-SupportState{$o=Get-CimInstance Win32_OperatingSystem;$c=Get-CimInstance Win32_ComputerSystem;[pscustomobject]@{Supported=($o.Caption-match'Windows 11'-and$c.Manufacturer-match'HP|Hewlett-Packard');OS=$o.Caption;Build=$o.BuildNumber;Manufacturer=$c.Manufacturer;Model=$c.Model;Elevated=Test-IsElevated}}
function Test-EnterpriseManaged{$c=Get-CimInstance Win32_ComputerSystem;$s=[ordered]@{DomainJoined=[bool]$c.PartOfDomain;MdmEnrollments=@(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Enrollments' -ErrorAction SilentlyContinue).Count;PolicyManager=Test-Path 'HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device';ConfigMgr=[bool](Get-Service CcmExec -ErrorAction SilentlyContinue)};[pscustomobject]@{Managed=($s.DomainJoined-or$s.MdmEnrollments-gt 0-or$s.PolicyManager-or$s.ConfigMgr);Signals=$s}}
function Resolve-Exe([string]$Command){$x=[Environment]::ExpandEnvironmentVariables($Command).Trim();if($x-match'^\s*"([^"]+\.exe)"'){$p=$matches[1]}elseif($x-match'^\s*([^\s]+\.exe)'){$p=$matches[1]}else{return $null};try{[IO.Path]::GetFullPath($p)}catch{$null}}
function Test-Protected([string]$Name,[string]$Command){$x=($Name+' '+$Command).ToLowerInvariant();foreach($t in $script:Protected){if($x.Contains($t)){return $true}};$false}
function Get-Publisher([string]$Path){if(!(Test-Path -LiteralPath $Path -PathType Leaf)){return $null};$s=Get-AuthenticodeSignature -LiteralPath $Path;$sub=if($s.SignerCertificate){$s.SignerCertificate.Subject}else{$null};[pscustomobject]@{Status=$s.Status.ToString();Subject=$sub;Valid=($s.Status-eq'Valid'-and$sub-match'(?i)(Logitech|Logi)')}}
function Test-Identity([string]$Name,[string]$Command,[string]$Exe){if(Test-Protected $Name $Command){return $false};$file=[IO.Path]::GetFileName($Exe);$nameOk=$Name-match'(?i)(SetPoint|Logitech SetPoint|Logitech Event Manager)';$exeOk=$file-match'(?i)^SetPoint(II)?\.exe$'-and$Exe-match'(?i)\\Logitech\\.*SetPoint';$bad=($Name+' '+$Command)-match'(?i)(update|updater|firmware|driver|receiver|unifying)';$nameOk-and$exeOk-and!$bad}
function Get-Candidates{
  $r=foreach($path in $script:RunPaths){if(!(Test-Path -LiteralPath $path)){continue};$k=Get-Item -LiteralPath $path;foreach($n in $k.GetValueNames()){$d=[string]$k.GetValue($n,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);$e=Resolve-Exe $d;if(!$e-or!(Test-Identity $n $d $e)){continue};$p=Get-Publisher $e;if(!$p-or!$p.Valid){continue};[pscustomobject]@{Path=$path;Name=$n;Kind=$k.GetValueKind($n).ToString();Data=$d;Executable=$e;PublisherStatus=$p.Status;PublisherSubject=$p.Subject;Scope=if($path.StartsWith('HKCU:')){'CurrentUser'}else{'LocalMachine'}}}};@($r)
}
function Assert-One([object[]]$C){if($C.Count-eq 0){throw'No eligible Logitech SetPoint startup registration was found.'};if($C.Count-gt 1){throw'Multiple eligible Logitech SetPoint startup registrations were found.'};if($C[0].Scope-eq'LocalMachine'-and!(Test-IsElevated)){throw'Elevation is required for machine-wide state.'}}
function Save-State([object[]]$C){Assert-One $C;$s=[ordered]@{schemaVersion=1;experiment=$script:Experiment;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;entry=$C[0]};$p=Split-Path -Parent $StatePath;if($p-and!(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};$s|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $StatePath -Encoding UTF8;$s}
function Read-State{if(!(Test-Path -LiteralPath $StatePath)){throw"State file missing: $StatePath"};$s=Get-Content -LiteralPath $StatePath -Raw|ConvertFrom-Json;$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;if($s.schemaVersion-ne 1-or$s.experiment-ne$script:Experiment-or$s.machine-ne$env:COMPUTERNAME-or$s.userSid-ne$sid){throw'State identity validation failed.'};$s}
function Test-Removed($S){if(!(Test-Path -LiteralPath $S.entry.Path)){return $true};$k=Get-Item -LiteralPath $S.entry.Path;!($k.GetValueNames()-contains[string]$S.entry.Name)}
function Test-Restored($S){if(!(Test-Path -LiteralPath $S.entry.Path)){return $false};$k=Get-Item -LiteralPath $S.entry.Path;if(!($k.GetValueNames()-contains[string]$S.entry.Name)){return $false};$d=[string]$k.GetValue($S.entry.Name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames);$d-eq[string]$S.entry.Data-and$k.GetValueKind($S.entry.Name).ToString()-eq[string]$S.entry.Kind}
try{
 $sup=Get-SupportState;Write-ExpLog support-detection $(if($sup.Supported){'pass'}else{'unsupported'}) @{os=$sup.OS;build=$sup.Build;manufacturer=$sup.Manufacturer;model=$sup.Model;elevated=$sup.Elevated};if(!$sup.Supported){throw'EXP-081 supports HP Windows 11 systems only.'}
 $m=Test-EnterpriseManaged;Write-ExpLog enterprise-management-detection $(if($m.Managed){'refused'}else{'pass'}) @{signals=$m.Signals};if($m.Managed){throw'Enterprise-management signals are present; mutation is refused.'}
 switch($Action){
  'Check'{$c=Get-Candidates;Write-ExpLog candidate-inventory pass @{count=$c.Count;names=@($c.Name);paths=@($c.Path)};$c}
  'Capture'{$s=Save-State (Get-Candidates);Write-ExpLog state-capture pass @{path=$s.entry.Path;name=$s.entry.Name};$s}
  'DryRun'{$c=Get-Candidates;Assert-One $c;Write-ExpLog dry-run pass @{path=$c[0].Path;name=$c[0].Name};[pscustomobject]@{WouldRemove=$c[0];StatePath=$StatePath}}
  'Apply'{$s=if(Test-Path $StatePath){Read-State}else{Save-State (Get-Candidates)};if(Test-Removed $s){Write-ExpLog apply idempotent @{path=$s.entry.Path;name=$s.entry.Name};break};$c=Get-Candidates;Assert-One $c;if($c[0].Path-ne$s.entry.Path-or$c[0].Name-ne$s.entry.Name-or$c[0].Data-ne$s.entry.Data-or$c[0].Kind-ne$s.entry.Kind-or$c[0].PublisherSubject-ne$s.entry.PublisherSubject){throw'Current registration differs from captured state.'};if($PSCmdlet.ShouldProcess("$($s.entry.Path)::$($s.entry.Name)",'Remove SetPoint startup registration')){Remove-ItemProperty -LiteralPath $s.entry.Path -Name $s.entry.Name};if(!(Test-Removed $s)){throw'Apply verification failed.'};Write-ExpLog apply pass @{path=$s.entry.Path;name=$s.entry.Name};$true}
  'Verify'{$s=Read-State;$ok=Test-Removed $s;Write-ExpLog verify $(if($ok){'pass'}else{'fail'}) @{};if(!$ok){throw'Removal verification failed.'};$true}
  'VerifyReboot'{$s=Read-State;$ok=Test-Removed $s;$boot=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime;Write-ExpLog verify-reboot $(if($ok){'pass'}else{'fail'}) @{bootTime=$boot};if(!$ok){throw'Reboot persistence verification failed.'};$true}
  'Rollback'{$s=Read-State;if(!(Test-Removed $s)){throw'Rollback refused because the registry value already exists.'};$p=Get-Publisher ([string]$s.entry.Executable);if(!$p-or!$p.Valid-or$p.Subject-ne[string]$s.entry.PublisherSubject){throw'Rollback publisher identity validation failed.'};if($PSCmdlet.ShouldProcess("$($s.entry.Path)::$($s.entry.Name)",'Restore SetPoint startup registration')){if(!(Test-Path $s.entry.Path)){New-Item -Path $s.entry.Path -Force|Out-Null};New-ItemProperty -LiteralPath $s.entry.Path -Name $s.entry.Name -Value $s.entry.Data -PropertyType $s.entry.Kind -Force|Out-Null};if(!(Test-Restored $s)){throw'Rollback verification failed.'};Write-ExpLog rollback pass @{path=$s.entry.Path;name=$s.entry.Name};$true}
 }
}catch{Write-ExpLog failure fail @{message=$_.Exception.Message;type=$_.Exception.GetType().FullName};throw}
